            g.FillPolygon(br, new Point[] { new Point(center.X - 16, center.Y - 30 - offsetY + 4), new Point(center.X - 16 + 32, center.Y - 30 - offsetY + 4), new Point(center.X - 16 + 32, center.Y - 30 - offsetY + 24 + 4), new Point(center.X - 16, center.Y - 30 - offsetY + 24 + 4) });
            g.FillEllipse(br, bot);
            g.DrawEllipse(pen, bot);
            g.FillEllipse(br, top);
            g.DrawEllipse(pen, top);
            g.DrawLine(pen, center.X - 16, center.Y - 30 - offsetY + 4, center.X - 16, center.Y - 30 - offsetY + 24 + 4);
            g.DrawLine(pen, center.X - 16 + 32, center.Y - 30 - offsetY + 4, center.X - 16 + 32, center.Y - 30 - offsetY + 24 + 4);
        }
        // Layer: Head
        using (var br = new SolidBrush(Color.FromArgb(240, skinColor.R, skinColor.G, skinColor.B)))
        using (var pen = new Pen(Color.FromArgb(240, accentColor.R, accentColor.G, accentColor.B), 1.2f))
        {
            var r = new Rectangle(center.X - 11, center.Y - 53 - offsetY, 22, 22);
            g.FillEllipse(br, r);
            g.DrawEllipse(pen, r);
        }
        using (var br = new SolidBrush(Color.FromArgb(255, 255, 255, 255)))
        using (var pen = new Pen(Color.FromArgb(255, 51, 51, 51), 0.8f))
        {
            var r = new Rectangle(center.X - 8, center.Y - 46 - offsetY, 4, 4);
            g.FillEllipse(br, r);
            g.DrawEllipse(pen, r);
        }
        using (var br = new SolidBrush(Color.FromArgb(255, 255, 255, 255)))
        using (var pen = new Pen(Color.FromArgb(255, 51, 51, 51), 0.8f))
        {
            var r = new Rectangle(center.X + 4, center.Y - 46 - offsetY, 4, 4);
            g.FillEllipse(br, r);
            g.DrawEllipse(pen, r);
        }
        // Layer: FX
        using (var br = new SolidBrush(Color.FromArgb(150, custom1.R, custom1.G, custom1.B)))
        using (var pen = new Pen(Color.FromArgb(150, 68, 136, 255), 0.5f))
        {
            Point[] pts = { new Point(center.X - 3 + 6 / 2, center.Y - 54 - offsetY), new Point(center.X - 3 + 6, center.Y - 54 - offsetY + 6 / 2), new Point(center.X - 3 + 6 / 2, center.Y - 54 - offsetY + 6), new Point(center.X - 3, center.Y - 54 - offsetY + 6 / 2) };
            g.FillPolygon(br, pts);
            g.DrawPolygon(pen, pts);
        }
    }

